// Scan is used internally from Parse.
func (p *Parser) Scan() (r scanner.Token) {
	return p.sc.Scan()
}

// init initalizes 'p' with content in 'src', assuming it comes from 'name'.
// 'src' becomes "owned" by 'p'. init invalidates any pre-existing ASTs produced by 'p'. Mutating
// 'src' invalidates the current AST returned from any parsing function called after init.
func (p *Parser) init(name string, src []byte) (err error) {
	p.eof = false
	p.errBudget = 10
	p.off = 0
	p.src = src
	p.tok = scanner.Token{}
	p.tokIndex = 0
	p.sc = scanner.NewRecScanner(name, p.src, p.scan, int(white_space))
	return nil
}

// AddExpr grammar:
//
//	AddExpr = MulExpr  { AddOp MulExpr  } .
//
//	State 0
//		on  at, bang, color, elem_ref, float_lit, ident, int_lit, kw_const, kw_func, lbrace, lbracket, lparen, minus, raw_str, str_full, str_start, triple_full, triple_start, unit_lit
//			call MulExpr and goto state 1
//	State 1
//		Accept
//		on  minus, plus
//			call AddOp and goto state 0
//
// AddExpr is used internally from Parse.
func (p *Parser) AddExpr() (r []int32) {
	accept, errorSet := false, 0
	r = append(p.get(), -int32(AddExpr), 0)
state0:
	accept, errorSet = false, 59
	switch Symbol(p.tok.Ch) {
	case at, bang, color, elem_ref, float_lit, ident, int_lit, kw_const, kw_func, lbrace, lbracket, lparen, minus, raw_str, str_full, str_start, triple_full, triple_start, unit_lit:
		r = p.add(r, p.MulExpr())
		goto state1
	}
	return p.stop(r, accept, errorSet)
state1:
	accept, errorSet = true, 103
	switch Symbol(p.tok.Ch) {
	case minus, plus:
		r = p.add(r, p.AddOp())
		goto state0
	}
	return p.stop(r, accept, errorSet)
}

// AddOp grammar:
//
//	AddOp = plus | minus .
//
//	State 0
//		on  minus, plus
//			shift and goto state 1
//	State 1
//		Accept
//
// AddOp is used internally from Parse.
func (p *Parser) AddOp() (r []int32) {
	accept, errorSet := false, 0
	r = append(p.get(), -int32(AddOp), 0)
	// state0:
	accept, errorSet = false, 103
	switch Symbol(p.tok.Ch) {
	case minus, plus:
		r = append(r, p.shift())
		goto state1
	}
	return p.stop(r, accept, errorSet)
state1:
	accept, errorSet = true, 0
	return p.stop(r, accept, errorSet)
}

// AndExpr grammar:
//
//	AndExpr = EqExpr   { land EqExpr   } .
//
//	State 0
//		on  at, bang, color, elem_ref, float_lit, ident, int_lit, kw_const, kw_func, lbrace, lbracket, lparen, minus, raw_str, str_full, str_start, triple_full, triple_start, unit_lit
//			call EqExpr and goto state 1
//	State 1
//		Accept
//		on  land
//			shift and goto state 0
//
// AndExpr is used internally from Parse.
func (p *Parser) AndExpr() (r []int32) {
	accept, errorSet := false, 0
	r = append(p.get(), -int32(AndExpr), 0)
state0:
	accept, errorSet = false, 56
	switch Symbol(p.tok.Ch) {
	case at, bang, color, elem_ref, float_lit, ident, int_lit, kw_const, kw_func, lbrace, lbracket, lparen, minus, raw_str, str_full, str_start, triple_full, triple_start, unit_lit:
		r = p.add(r, p.EqExpr())
		goto state1
	}
	return p.stop(r, accept, errorSet)
state1:
	accept, errorSet = true, 96
	switch Symbol(p.tok.Ch) {
	case land:
		r = append(r, p.shift())
		goto state0
	}
	return p.stop(r, accept, errorSet)
}

// AnonField grammar:
//
//	AnonField =
//	      ellipsis Expr
//	    | ident assign Expr
//	    .
//
//	State 0
//		on  ellipsis
//			shift and goto state 1
//		on  ident
//			shift and goto state 3
//	State 1
//		on  at, bang, color, elem_ref, float_lit, ident, int_lit, kw_const, kw_func, lbrace, lbracket, lparen, minus, raw_str, str_full, str_start, triple_full, triple_start, unit_lit
//			call Expr and goto state 2
//	State 2
//		Accept
//	State 3
//		on  assign
//			shift and goto state 1
//
// AnonField is used internally from Parse.
func (p *Parser) AnonField() (r []int32) {
	accept, errorSet := false, 0
	r = append(p.get(), -int32(AnonField), 0)
	// state0:
	accept, errorSet = false, 12
	switch Symbol(p.tok.Ch) {
	case ellipsis:
		r = append(r, p.shift())
		goto state1
	case ident:
		r = append(r, p.shift())
		goto state3
	}
	return p.stop(r, accept, errorSet)
state1:
	accept, errorSet = false, 52
	switch Symbol(p.tok.Ch) {
	case at, bang, color, elem_ref, float_lit, ident, int_lit, kw_const, kw_func, lbrace, lbracket, lparen, minus, raw_str, str_full, str_start, triple_full, triple_start, unit_lit:
		r = p.add(r, p.Expr())
		goto state2
	}
	return p.stop(r, accept, errorSet)
state2:
	accept, errorSet = true, 0
	return p.stop(r, accept, errorSet)
state3:
	accept, errorSet = false, 43
	switch Symbol(p.tok.Ch) {
	case assign:
		r = append(r, p.shift())
		goto state1
	}
	return p.stop(r, accept, errorSet)
}

// AnonStructLit grammar:
//
//	# Anonymous struct literal: {field = expr, …}  — starts with lbrace, unambiguous.
//	AnonStructLit = lbrace [ AnonField { ( comma | semi ) AnonField } [ comma | semi ] ] rbrace .
//
//	State 0
//		on  lbrace
//			shift and goto state 1
//	State 1
//		on  rbrace
//			shift and goto state 2
//		on  ellipsis, ident
//			call AnonField and goto state 3
//	State 2
//		Accept
//	State 3
//		on  comma, semi
//			shift and goto state 1
//		on  rbrace
//			shift and goto state 2
//
// AnonStructLit is used internally from Parse.
func (p *Parser) AnonStructLit() (r []int32) {
	accept, errorSet := false, 0
	r = append(p.get(), -int32(AnonStructLit), 0)
	// state0:
	accept, errorSet = false, 98
	switch Symbol(p.tok.Ch) {
	case lbrace:
		r = append(r, p.shift())
		goto state1
	}
	return p.stop(r, accept, errorSet)
state1:
	accept, errorSet = false, 11
	switch Symbol(p.tok.Ch) {
	case rbrace:
		r = append(r, p.shift())
		goto state2
	case ellipsis, ident:
		r = p.add(r, p.AnonField())
		goto state3
	}
	return p.stop(r, accept, errorSet)
state2:
	accept, errorSet = true, 0
	return p.stop(r, accept, errorSet)
state3:
	accept, errorSet = false, 119
	switch Symbol(p.tok.Ch) {
	case comma, semi:
		r = append(r, p.shift())
		goto state1
	case rbrace:
		r = append(r, p.shift())
		goto state2
	}
	return p.stop(r, accept, errorSet)
}

// Arg grammar:
//
//	Arg =
//	      colon ident [ Type ] [ assign Expr ]
//	    | ellipsis Expr
//	    | ident IdentArgCont
//	    | bang UnaryExpr ArgExprCont
//	    | minus UnaryExpr ArgExprCont
//	    | kw_const UnaryExpr ArgExprCont
//	    | NonIdentPrimary { StmtPostfixOp } ArgExprCont
//	    .
//
//	State 0
//		on  bang, kw_const, minus
//			shift and goto state 1
//		on  colon
//			shift and goto state 4
//		on  ellipsis
//			shift and goto state 6
//		on  ident
//			shift and goto state 8
//		on  at, color, elem_ref, float_lit, int_lit, kw_func, lbrace, lbracket, lparen, raw_str, str_full, str_start, triple_full, triple_start, unit_lit
//			call NonIdentPrimary and goto state 9
//	State 1
//		on  at, bang, color, elem_ref, float_lit, ident, int_lit, kw_const, kw_func, lbrace, lbracket, lparen, minus, raw_str, str_full, str_start, triple_full, triple_start, unit_lit
//			call UnaryExpr and goto state 2
//	State 2
//		Accept
//		on  eq, gt, gte, land, lor, lt, lte, minus, neq, percent, plus, question, slash, star
//			call ArgExprCont and goto state 3
//	State 3
//		Accept
//	State 4
//		on  ident
//			shift and goto state 5
//	State 5
//		Accept
//		on  assign
//			shift and goto state 6
//		on  ident, kw_component, kw_enum, kw_func, kw_struct, kw_unit
//			call Type and goto state 7
//	State 6
//		on  at, bang, color, elem_ref, float_lit, ident, int_lit, kw_const, kw_func, lbrace, lbracket, lparen, minus, raw_str, str_full, str_start, triple_full, triple_start, unit_lit
//			call Expr and goto state 3
//	State 7
//		Accept
//		on  assign
//			shift and goto state 6
//	State 8
//		Accept
//		on  assign, dot, elem_ref, eq, gt, gte, land, lbrace, lbracket, lor, lparen, lt, lte, minus, neq, percent, plus, question, slash, star
//			call IdentArgCont and goto state 3
//	State 9
//		Accept
//		on  dot, elem_ref, lbrace, lbracket, lparen
//			call StmtPostfixOp and goto state 9
//		on  eq, gt, gte, land, lor, lt, lte, minus, neq, percent, plus, question, slash, star
//			call ArgExprCont and goto state 3
