func (p *Parser) Stmt() (r []int32) {
	accept, errorSet := false, 0
	r = append(p.get(), -int32(Stmt), 0)
	// state0:
	accept, errorSet = false, 78
	switch Symbol(p.tok.Ch) {
	case kw_return:
		r = append(r, p.shift())
		goto state1
	case kw_import:
		r = p.add(r, p.ImportDecl())
		goto state2
	case kw_struct:
		r = p.add(r, p.StructDecl())
		goto state2
	case kw_enum:
		r = p.add(r, p.EnumDecl())
		goto state2
	case kw_unit:
		r = p.add(r, p.UnitDecl())
		goto state2
	case kw_const:
		r = p.add(r, p.ConstDecl())
		goto state2
	case kw_var:
		r = p.add(r, p.VarDecl())
		goto state2
	case kw_func:
		r = p.add(r, p.FuncDecl())
		goto state2
	case kw_component:
		r = p.add(r, p.ComponentDecl())
		goto state2
	case at, color, elem_ref, float_lit, ident, int_lit, lbrace, lbracket, lparen, raw_str, str_full, str_start, triple_full, triple_start, unit_lit:
		r = p.add(r, p.VisualOrStmt())
		goto state2
	case kw_if:
		r = p.add(r, p.IfNode())
		goto state2
	case kw_for:
		r = p.add(r, p.ForNode())
		goto state2
	case kw_platform:
		r = p.add(r, p.PlatformNode())
		goto state2
	}
	return p.stop(r, accept, errorSet)
state1:
	accept, errorSet = true, 52
	switch Symbol(p.tok.Ch) {
	case at, bang, color, elem_ref, float_lit, ident, int_lit, kw_const, kw_func, lbrace, lbracket, lparen, minus, raw_str, str_full, str_start, triple_full, triple_start, unit_lit:
		r = p.add(r, p.Expr())
		goto state2
	}
	return p.stop(r, accept, errorSet)
state2:
	accept, errorSet = true, 0
	return p.stop(r, accept, errorSet)
}

