//			call Type and goto state 4
//		on  at
//			call VarHandler and goto state 3
//	State 2
//		on  at, bang, color, elem_ref, float_lit, ident, int_lit, kw_const, kw_func, lbrace, lbracket, lparen, minus, raw_str, str_full, str_start, triple_full, triple_start, unit_lit
//			call Expr and goto state 3
//	State 3
//		Accept
//		on  at
//			call VarHandler and goto state 3
//	State 4
//		Accept
//		on  assign
//			shift and goto state 2
//		on  at
//			call VarHandler and goto state 3
//
// VarSpec is used internally from Parse.
func (p *Parser) VarSpec() (r []int32) {
	accept, errorSet := false, 0
	r = append(p.get(), -int32(VarSpec), 0)
	// state0:
	accept, errorSet = false, 40
	switch Symbol(p.tok.Ch) {
	case ident:
		r = p.add(r, p.IdentList())
		goto state1
	}
	return p.stop(r, accept, errorSet)
state1:
	accept, errorSet = true, 3
	switch Symbol(p.tok.Ch) {
	case assign:
		r = append(r, p.shift())
		goto state2
	case ident, kw_component, kw_enum, kw_func, kw_struct, kw_unit:
		r = p.add(r, p.Type())
		goto state4
	case at:
		r = p.add(r, p.VarHandler())
		goto state3
	}
	return p.stop(r, accept, errorSet)
state2:
	accept, errorSet = false, 52
	switch Symbol(p.tok.Ch) {
	case at, bang, color, elem_ref, float_lit, ident, int_lit, kw_const, kw_func, lbrace, lbracket, lparen, minus, raw_str, str_full, str_start, triple_full, triple_start, unit_lit:
		r = p.add(r, p.Expr())
		goto state3
	}
	return p.stop(r, accept, errorSet)
state3:
	accept, errorSet = true, 93
	switch Symbol(p.tok.Ch) {
	case at:
		r = p.add(r, p.VarHandler())
		goto state3
	}
	return p.stop(r, accept, errorSet)
state4:
	accept, errorSet = true, 4
	switch Symbol(p.tok.Ch) {
	case assign:
		r = append(r, p.shift())
		goto state2
	case at:
		r = p.add(r, p.VarHandler())
		goto state3
	}
	return p.stop(r, accept, errorSet)
}

// VisualOrStmt grammar:
//
//	# ── Visual nodes + expression statements ──────────────────────────────────────
//	#
//	# VisualOrStmt unifies: visual node declarations, function/emit calls, assignments,
//	# and toggles. All parse as StatementPrimary followed by PostfixOps.
//	#
//	# StmtBlock is a PostfixOp, so trailing bodies attach naturally:
//	#   Button { Text("hi") }           → ident + StmtBlock postfix
//	#   Button(text="hi") { }           → ident + call postfix + StmtBlock postfix
//	#   @tick { progress += 0.01 }      → at-ident primary + StmtBlock postfix
//	#   @click(e) { doSomething() }     → at-ident primary + call postfix + StmtBlock postfix
//	#   output { go { bubbletea { } } } → ident primary + StmtBlock postfix (nested)
//	#   timer(interval=1s, @tick { })   → ident + call postfix (with @tick in ArgList)
//	#
//	# kw_func is excluded from StatementPrimary — handled by FuncDecl in Stmt.
//
//	VisualOrStmt = StatementPrimary { StmtPostfixOp } [ AssignOp Expr | bangbang | IncDecOp ] .
//
//	State 0
//		on  at, color, elem_ref, float_lit, ident, int_lit, lbrace, lbracket, lparen, raw_str, str_full, str_start, triple_full, triple_start, unit_lit
//			call StatementPrimary and goto state 1
//	State 1
//		Accept
//		on  bangbang
//			shift and goto state 2
//		on  assign, minus_assign, pct_assign, plus_assign, slash_assign, star_assign
//			call AssignOp and goto state 3
//		on  dot, elem_ref, lbrace, lbracket, lparen
//			call StmtPostfixOp and goto state 1
//		on  minus_minus, plus_plus
//			call IncDecOp and goto state 2
//	State 2
//		Accept
//	State 3
//		on  at, bang, color, elem_ref, float_lit, ident, int_lit, kw_const, kw_func, lbrace, lbracket, lparen, minus, raw_str, str_full, str_start, triple_full, triple_start, unit_lit
//			call Expr and goto state 2
//
// VisualOrStmt is used internally from Parse.
func (p *Parser) VisualOrStmt() (r []int32) {
	accept, errorSet := false, 0
	r = append(p.get(), -int32(VisualOrStmt), 0)
	// state0:
	accept, errorSet = false, 81
	switch Symbol(p.tok.Ch) {
	case at, color, elem_ref, float_lit, ident, int_lit, lbrace, lbracket, lparen, raw_str, str_full, str_start, triple_full, triple_start, unit_lit:
		r = p.add(r, p.StatementPrimary())
		goto state1
	}
	return p.stop(r, accept, errorSet)
state1:
	accept, errorSet = true, 6
	switch Symbol(p.tok.Ch) {
	case bangbang:
		r = append(r, p.shift())
		goto state2
	case assign, minus_assign, pct_assign, plus_assign, slash_assign, star_assign:
		r = p.add(r, p.AssignOp())
		goto state3
	case dot, elem_ref, lbrace, lbracket, lparen:
		r = p.add(r, p.StmtPostfixOp())
		goto state1
	case minus_minus, plus_plus:
		r = p.add(r, p.IncDecOp())
		goto state2
	}
	return p.stop(r, accept, errorSet)
state2:
	accept, errorSet = true, 0
	return p.stop(r, accept, errorSet)
state3:
	accept, errorSet = false, 52
	switch Symbol(p.tok.Ch) {
	case at, bang, color, elem_ref, float_lit, ident, int_lit, kw_const, kw_func, lbrace, lbracket, lparen, minus, raw_str, str_full, str_start, triple_full, triple_start, unit_lit:
		r = p.add(r, p.Expr())
		goto state2
	}
	return p.stop(r, accept, errorSet)
}

func (p *Parser) shift() (r int32) {
	r = p.tokIndex
	if !p.eof {
		p.tok = p.Scan()
		p.tokIndex++
		p.eof = p.tok.Ch == rune(TOK_EOF)
	}
	return r
}

func (p *Parser) get() (r []int32) {
	if n := len(p.cache); n != 0 {
		r = p.cache[n-1][:0]
		p.cache = p.cache[:n-1]
	}
	return r
}

func (p *Parser) add(r, s []int32) (t []int32) {
	p.cache = append(p.cache, s)
	return append(r, s...)
}

func (p *Parser) stop(r []int32, accept bool, errorSet int) []int32 {
	r[1] = int32(len(r) - 2)
	if !accept {
		p.err(p.tok.Position(), "%q [%s]: expected %v", p.tok.Src(), Symbol(p.tok.Ch), errorSets[errorSet])
	}
	return r
}

// EOF reports whether the parser lookahead token is EOF.
func (p *Parser) EOF() bool {
	return p.eof
}

// Token returns the n-th token in 'p'. Token panics if 'n' is out of range.
func (p *Parser) Token(n int32) (r scanner.Token) {
	return p.sc.Token(int(n))
}

// Parse parses 'src'. 'src' becomes "owned" by the parser and must not be
// mutated afterwards.
func (p *Parser) Parse(name string, src []byte) (ast []int32, err error) {
	if err = p.init(name, src); err != nil {
		return nil, err
	}

	defer func() {
		switch e := recover(); x := e.(type) {
		case nil:
			// ok
		case scanner.ErrList:
			err = x
		case error:
			err = errors.Join(err, x)
		default:
			err = errors.Join(err, fmt.Errorf("%v", x))
		}
	}()

	p.tok = p.Scan()
	ast = p.Document()
	return ast, p.sc.Err()
}

func (p *Parser) err0(pos token.Position, s string, args ...any) {
	p.sc.AddErr(pos, s, args...)
	if p.errBudget--; p.errBudget == 0 {
		p.sc.AddErr(pos, "too many errors")
	}
}

func (p *Parser) err(pos token.Position, s string, args ...any) {
	p.err0(pos, s, args...)
	p.shift()
	if p.eof {
		panic(p.sc.Err())
	}
}
